const portraitHost=document.querySelector('#judoka-canvas'),portrait=document.querySelector('.mannequin-portrait'),stagePortrait=document.querySelector('.judoka-stage');
const motionButton=document.querySelector('#model-motion'),frontButton=document.querySelector('#view-front'),backButton=document.querySelector('#view-back');const portraitReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let portraitSide='front',portraitMotion=!portraitReduced,manualUntil=0,swipeX=null,lastChapterSide='front';
function showPortrait(side,manual=false){portraitSide=side;portrait.classList.toggle('show-back',side==='back');frontButton.setAttribute('aria-pressed',side==='front');backButton.setAttribute('aria-pressed',side==='back');document.querySelector('#portrait-caption').textContent=side==='front'?'L’IDENTITÉ DU CLUB':'LE BOND EN AVANT';document.querySelector('#portrait-side').textContent=side==='front'?'FACE / 01':'DOS / 02';if(manual)manualUntil=performance.now()+7000;}
function setPortraitMotion(){stagePortrait.classList.toggle('motion-paused',!portraitMotion);motionButton.setAttribute('aria-pressed',portraitMotion);motionButton.textContent=portraitMotion?'Pause':'Animer';motionButton.setAttribute('aria-label',portraitMotion?'Suspendre les mouvements du mannequin':'Activer les mouvements du mannequin');}setPortraitMotion();
frontButton.onclick=()=>showPortrait('front',true);backButton.onclick=()=>showPortrait('back',true);motionButton.onclick=()=>{portraitMotion=!portraitMotion;setPortraitMotion()};
portraitHost.addEventListener('pointerdown',e=>{swipeX=e.clientX;portraitHost.setPointerCapture(e.pointerId)});portraitHost.addEventListener('pointerup',e=>{if(swipeX!==null&&Math.abs(e.clientX-swipeX)>25)showPortrait(portraitSide==='front'?'back':'front',true);swipeX=null;});portraitHost.addEventListener('pointercancel',()=>swipeX=null);
portraitHost.addEventListener('pointermove',e=>{if(portraitReduced||!portraitMotion||e.pointerType!=='mouse')return;const r=portraitHost.getBoundingClientRect();portrait.style.setProperty('--tilt-x',-((e.clientY-r.top)/r.height-.5)*5+'deg');portrait.style.setProperty('--tilt-y',((e.clientX-r.left)/r.width-.5)*9+'deg');});portraitHost.addEventListener('pointerleave',()=>{portrait.style.setProperty('--tilt-x','0deg');portrait.style.setProperty('--tilt-y','0deg')});
// Wheel remains native page scrolling; the narrative selects the face or back.
portraitHost.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();showPortrait(e.key==='Home'||e.key==='ArrowLeft'?'front':'back',true);}});
window.addEventListener('judoka-scroll',e=>{const p=e.detail.progress;const side=p>.43&&p<.86?'back':'front';if(side!==lastChapterSide){lastChapterSide=side;if(performance.now()>manualUntil)showPortrait(side);}if(!portraitReduced&&portraitMotion){stagePortrait.style.setProperty('--portrait-scale',String(.94+Math.sin(p*Math.PI)*.1));stagePortrait.style.setProperty('--portrait-turn',(-4+p*8)+'deg');}});
const manifesto=document.querySelector('.scroll-manifesto'),manifestoLines=[...document.querySelectorAll('.manifesto-sticky h2 span')];let motionScheduled=false;
function updateScrollEffects(){motionScheduled=false;const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress i').style.transform=`scaleX(${max>0?scrollY/max:0})`;const r=manifesto.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/Math.max(1,r.height-innerHeight)));manifestoLines.forEach((line,i)=>{const reveal=portraitReduced?1:Math.max(0,Math.min(1,(p*4-i)*1.7+.12));line.style.setProperty('--word-progress',reveal);});if(!portraitReduced){document.querySelectorAll('.club-photo,.action-photo').forEach(card=>{const b=card.getBoundingClientRect();const t=Math.max(-1,Math.min(1,(b.top+b.height/2-innerHeight/2)/innerHeight));card.style.setProperty('--image-shift',t*-18+'px');});}}
addEventListener('scroll',()=>{if(!motionScheduled){motionScheduled=true;requestAnimationFrame(updateScrollEffects)}},{passive:true});addEventListener('resize',updateScrollEffects);updateScrollEffects();showPortrait('front');
